contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount, bool shutdown) public payable {
        // Ensure the caller is the operator set in the contract.
        require(c.operator() == address(this), "inv: test must be operator");

        // If the pool is shutdown, the deposit should not increase allowance.
        // Otherwise, calling depositAndStake with amount should increase the allowance exactly by amount.
        if (shutdown != c.isCvxShutdown()) {
            // No meaningful assertion can be made; avoid false positives.
            return;
        }

        IERC20 token = IERC20(address(c.clpToken()));
        uint256 beforeAllowance = token.allowance(address(c), address(c.booster()));

        // Call the state-changing function as a top-level statement.
        c.depositAndStake(amount);

        uint256 afterAllowance = token.allowance(address(c), address(c.booster()));

        bool expectedIncrease = !c.isCvxShutdown();
        if (expectedIncrease) {
            assert(afterAllowance == beforeAllowance + amount);
        } else {
            assert(afterAllowance == beforeAllowance);
        }
    }

    receive() external payable {}
}

