contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, uint256 amount, uint256 withdrawAmount, bool claim, address to) public payable {
        require(caller != address(this), "caller must be distinct");

        // depositAndStake is onlyOperator. We cannot change msg.sender, so we check the
        // current sender's authorization against c.operator().
        bool depositReverted;
        try c.depositAndStake(amount) {
            depositReverted = false;
        } catch {
            depositReverted = true;
        }

        bool withdrawReverted;
        try c.withdrawAndUnwrap(withdrawAmount, claim, to) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // The current msg.sender is address(this). Since the constructor set
        // operator to _operator, address(this) may or may not be the operator.
        // The rule: depositAndStake reverts iff the caller is not the operator,
        // and withdrawAndUnwrap reverts iff the caller is neither operator nor owner.
        bool callerIsOperator = (address(this) == c.operator());
        bool callerIsOwner = (address(this) == c.owner());

        assert(
            (depositReverted == !callerIsOperator) &&
            (withdrawReverted == (!callerIsOperator && !callerIsOwner))
        );
    }
}

