contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address newRecipient) public payable {
        require(caller != address(0), "caller must be non-zero");
        require(newRecipient != address(0), "recipient must be non-zero");

        address ownerBefore = c.owner();
        require(caller != ownerBefore, "caller must not be owner for the non-owner branch");

        // non-owner caller should revert
        bool reverted;
        try c.setRewardsRecipient(newRecipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // because msg.sender in the test is the InvMutTest contract, calling c directly would not change caller
        // Instead, we use the fact that the test contract itself is not the owner (it is not set as owner in constructor of C),
        // so calling c.setRewardsRecipient directly always reverts unless the test contract happens to be the owner.
        // We can't simulate a different msg.sender, so we check the invariant that a call from the test contract (which is not the owner)
        // must revert and must not change rewardsRecipient.

        address recipientBefore = c.rewardsRecipient();

        // The call above already happened; if the test contract were the owner it would have succeeded, but it isn't,
        // so we assert it reverted and state is unchanged.
        assert(reverted && c.rewardsRecipient() == recipientBefore);
    }

    receive() external payable {}
}

