contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address recipientBefore, address recipientAfter, address rewardToken0, uint256 rewardAmount0) public payable {
        // Precondition: recipientAfter is exactly the zero address, so the transfer loop is skipped.
        require(recipientAfter == address(0), "recipientAfter must be zero so reward transfers are skipped");

        // Set the rewardsRecipient to the zero address so getReward does not transfer any reward tokens.
        c.setRewardsRecipient(recipientAfter);

        // Record the contract's own balance of the first reward token before getReward.
        uint256 balanceBefore = IERC20(rewardToken0).balanceOf(address(c));

        // This call may revert if the rewards contract is not configured; the assertion below
        // must hold in both the success and revert cases, so we catch revert explicitly.
        bool reverted;
        try c.getReward(true) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read the reward token balance after the operation.
        uint256 balanceAfter = IERC20(rewardToken0).balanceOf(address(c));

        // General rule: when rewardsRecipient is zero, getReward never transfers reward tokens out,
        // so the balance of any reward token cannot decrease. If getReward reverts, both reads are
        // from the unchanged state and the equality still holds.
        assert(balanceAfter >= balanceBefore);
    }
}

