contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address caller,
        uint32 newPid,
        address newToken,
        address newRewards,
        address newOperator,
        address newRecipient,
        address recoverTo,
        uint256 recoverAmount,
        uint256 depositAmount,
        uint256 withdrawAmount,
        bool claim,
        address withdrawTo,
        bool sendToOperator,
        bool claimExtras
    ) public payable {
        require(caller != address(0), "caller zero");

        address owner = c.owner();
        address operator = c.operator();

        bool onlyOwnerShouldWork = (caller == owner);
        bool onlyOperatorOrOwnerShouldWork = (caller == owner || caller == operator);

        bool revertedSetCvxPoolInfo;
        bool revertedSetOperator;
        bool revertedSetRewardsRecipient;
        bool revertedRecoverToken;
        bool revertedWithdrawAndUnwrap;
        bool revertedWithdrawAllAndUnwrap;

        if (caller == owner) {
            c.setCvxPoolInfo(newPid, newToken, newRewards);
            c.setOperator(newOperator);
            c.setRewardsRecipient(newRecipient);
            c.recoverToken(address(this), recoverTo, recoverAmount);
        } else {
            try c.setCvxPoolInfo(newPid, newToken, newRewards) {
                revertedSetCvxPoolInfo = false;
            } catch {
                revertedSetCvxPoolInfo = true;
            }
            try c.setOperator(newOperator) {
                revertedSetOperator = false;
            } catch {
                revertedSetOperator = true;
            }
            try c.setRewardsRecipient(newRecipient) {
                revertedSetRewardsRecipient = false;
            } catch {
                revertedSetRewardsRecipient = true;
            }
            try c.recoverToken(address(this), recoverTo, recoverAmount) {
                revertedRecoverToken = false;
            } catch {
                revertedRecoverToken = true;
            }
        }

        if (owner == caller || operator == caller) {
            try c.withdrawAndUnwrap(withdrawAmount, claim, withdrawTo) {
                revertedWithdrawAndUnwrap = false;
            } catch {
                revertedWithdrawAndUnwrap = true;
            }
        } else {
            try c.withdrawAndUnwrap(withdrawAmount, claim, withdrawTo) {
                revertedWithdrawAndUnwrap = false;
            } catch {
                revertedWithdrawAndUnwrap = true;
            }
        }

        if (owner == caller) {
            try c.withdrawAllAndUnwrap(claim, sendToOperator) {
                revertedWithdrawAllAndUnwrap = false;
            } catch {
                revertedWithdrawAllAndUnwrap = true;
            }
        } else {
            try c.withdrawAllAndUnwrap(claim, sendToOperator) {
                revertedWithdrawAllAndUnwrap = false;
            } catch {
                revertedWithdrawAllAndUnwrap = true;
            }
        }

        bool shouldHaveRevertedForOnlyOwner = !onlyOwnerShouldWork;
        bool shouldHaveRevertedForOnlyOperatorOrOwner = !onlyOperatorOrOwnerShouldWork;

        assert(
            (onlyOwnerShouldWork ||
                (revertedSetCvxPoolInfo &&
                    revertedSetOperator &&
                    revertedSetRewardsRecipient &&
                    revertedRecoverToken)) &&
                (!onlyOwnerShouldWork) ==
                (revertedSetCvxPoolInfo &&
                    revertedSetOperator &&
                    revertedSetRewardsRecipient &&
                    revertedRecoverToken) &&
                (!onlyOperatorOrOwnerShouldWork) ==
                revertedWithdrawAndUnwrap &&
                !onlyOperatorOrOwnerShouldWork &&
                (!onlyOwnerShouldWork) == revertedWithdrawAllAndUnwrap
        );
    }

    receive() external payable {}
}

