contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        bool callerIsOperator,
        uint256 amount,
        bool claim,
        address to
    ) public {
        // Sanity precondition: only Operator and owner are allowed to call withdrawAndUnwrap.
        if (to == address(0)) {
            to = address(0xdead);
        }

        uint256 clpBefore = c.clpToken().balanceOf(address(this));

        bool reverted;
        try c.withdrawAndUnwrap(amount, claim, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (reverted) {
            // Must revert only for unauthorized callers (msg.sender is this test contract).
            assert(c.operator() != address(this) && c.owner() != address(this));
        } else {
            // Authorized caller path: the contract must have transferred exactly `amount`
            // of clpToken to `to`, and its own CLP balance must have decreased by amount
            // or by as much as it could withdraw.
            uint256 clpAfter = c.clpToken().balanceOf(address(this));
            address recipient = to;
            uint256 recipientAfter = c.clpToken().balanceOf(recipient);
            // Conservation: any successful withdrawal cannot create CLP out of nowhere.
            assert(clpAfter + amount >= clpBefore);
            assert(recipientAfter >= amount);
        }
    }
}

