contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public payable {
        require(true);

        // ---- capture before state ----
        uint256 beforeBalance = c.clpToken().balanceOf(address(c));

        // ---- decide expected outcome ----
        bool enough = amount <= beforeBalance;
        bool reverted;

        // ---- act ----
        try c.recoverToken(address(c.clpToken()), address(this), amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // ---- read after state ----
        uint256 afterBalance = c.clpToken().balanceOf(address(c));

        // General rule: recoverToken succeeds exactly when c owns enough clpToken,
        // and whenever it succeeds c's clpToken balance decreases by exactly `amount`.
        if (enough) {
            assert(!reverted && afterBalance == beforeBalance - amount);
        } else {
            assert(reverted);
        }
    }
}

